package com.smarthospital.controller;
import com.smarthospital.model.User;import com.smarthospital.util.*;import javax.servlet.*;import javax.servlet.annotation.*;import javax.servlet.http.*;import java.io.*;import java.sql.*;import java.util.*;
@WebServlet("/my-duties") public class MyDutiesServlet extends HttpServlet{
 protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{User u=(User)req.getSession().getAttribute("user");try(Connection c=DB.getConnection()){List<Map<String,Object>>l=new ArrayList<>();String q="SELECT da.assignment_id,d.duty_id,d.duty_name,d.duty_date,d.start_time,d.end_time,d.priority,da.status,COALESCE((SELECT verification_status FROM documents doc WHERE doc.duty_id=d.duty_id AND doc.staff_id=da.staff_id ORDER BY doc.uploaded_at DESC LIMIT 1),'NOT_UPLOADED') FROM duty_assignments da JOIN duties d ON da.duty_id=d.duty_id JOIN staff s ON da.staff_id=s.staff_id WHERE s.user_id=? ORDER BY CASE WHEN d.duty_date>=CURDATE() THEN 0 ELSE 1 END,d.duty_date ASC,d.start_time ASC";try(PreparedStatement p=c.prepareStatement(q)){p.setInt(1,u.id());try(ResultSet r=p.executeQuery()){while(r.next()){Map<String,Object>m=new HashMap<>();for(int i=1;i<=9;i++)m.put("c"+i,r.getObject(i));l.add(m);}}}req.setAttribute("rows",l);req.getRequestDispatcher("/my-duties.jsp").forward(req,resp);}catch(Exception e){throw new ServletException(e);}}
 protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws IOException{User u=(User)req.getSession().getAttribute("user");String action=req.getParameter("action");try(Connection c=DB.getConnection()){int id=Integer.parseInt(req.getParameter("assignment_id"));String st="acknowledge".equals(action)?"ACKNOWLEDGED":"start".equals(action)?"IN_PROGRESS":"change".equals(action)?"CHANGE_REQUESTED":null;if(st==null)throw new IllegalArgumentException("Unsupported duty action.");try(PreparedStatement p=c.prepareStatement("UPDATE duty_assignments SET status=? WHERE assignment_id=? AND staff_id=(SELECT staff_id FROM staff WHERE user_id=?) AND status IN ('ASSIGNED','ACKNOWLEDGED')")){p.setString(1,st);p.setInt(2,id);p.setInt(3,u.id());if(p.executeUpdate()==0)throw new IllegalArgumentException("Duty cannot be changed in its current state.");}Audit.log(u.id(),"DUTY_STATUS",st+" assignment #"+id);resp.sendRedirect(req.getContextPath()+"/my-duties");}catch(Exception e){resp.sendError(400,e.getMessage());}}
}
